import{_ as e,a,b as r,c as t}from"./chunks/kuka_theme_4.7PEyRC9o.js";import{_ as l,a as i,b as n,c as s,d,e as c,f as h,g as u,h as g,i as m,j as p}from"./chunks/sort_declarations.DU86DpOi.js";import{_ as k}from"./chunks/inlay_hints.BQUZLqE3.js";import{_}from"./chunks/kuka_commands.D8cXdGAR.js";import{_ as f}from"./chunks/kuka_control_center.CLR_jZ0I.js";import{_ as K}from"./chunks/krc_backup_diff.FXLcgDew.js";import{_ as b}from"./chunks/control_flow_graph.hbF2msHR.js";import{_ as S}from"./chunks/cell_flowchart.DffnEFAW.js";import{_ as A,o as P,c as C,a0 as q}from"./chunks/framework.QP0FkqbW.js";const G=JSON.parse('{"title":"KUKA KRL Professional — Полная Вики и Энциклопедия Функционала (v1.8.5 Pro Hub)","description":"","frontmatter":{},"headers":[],"relativePath":"ru/guide/features.md","filePath":"ru/guide/features.md"}'),L={name:"ru/guide/features.md"};function I(D,o,x,R,T,O){return P(),C("div",null,[...o[0]||(o[0]=[q('<h1 id="kuka-krl-professional-—-полная-вики-и-энциклопедия-функционала-v1-8-5-pro-hub" tabindex="-1">KUKA KRL Professional — Полная Вики и Энциклопедия Функционала (v1.8.5 Pro Hub) <a class="header-anchor" href="#kuka-krl-professional-—-полная-вики-и-энциклопедия-функционала-v1-8-5-pro-hub" aria-label="Permalink to &quot;KUKA KRL Professional — Полная Вики и Энциклопедия Функционала (v1.8.5 Pro Hub)&quot;">​</a></h1><p>Добро пожаловать в интерактивный технический справочник <strong>KUKA KRL Professional Extension</strong> для VS Code.</p><p>Наше расширение — это специализированная среда разработки и статический анализатор промышленного класса, созданный инженерами-робототехниками для программирования промышленных роботов KUKA (KSS 8.3 / 8.5 / 8.6 / 8.7).</p><p>Ниже приведен подробнейший разбор всех <strong>26 ключевых функций</strong> расширения (15 бесплатных базовых и 11 премиальных промышленных инструментов), их практическая ценность на объекте, комбинации клавиш и видеодемонстрации.</p><hr><h2 id="🟢-часть-1-community-core-features-бесплатныи-базовыи-функционал" tabindex="-1">🟢 Часть 1. Community &amp; Core Features (Бесплатный базовый функционал) <a class="header-anchor" href="#🟢-часть-1-community-core-features-бесплатныи-базовыи-функционал" aria-label="Permalink to &quot;🟢 Часть 1. Community &amp; Core Features (Бесплатный базовый функционал)&quot;">​</a></h2><p>Базовый набор функций доступен бесплатно и кардинально превосходит стандартные редакторские плагины.</p><hr><h3 id="_1-синтаксическая-подсветка-krl-syntax-highlighting" tabindex="-1">1. Синтаксическая подсветка KRL (Syntax Highlighting) <a class="header-anchor" href="#_1-синтаксическая-подсветка-krl-syntax-highlighting" aria-label="Permalink to &quot;1. Синтаксическая подсветка KRL (Syntax Highlighting)&quot;">​</a></h3><ul><li><strong>Для чего нужна:</strong> Обычные текстовые редакторы отображают файлы <code>.src</code>, <code>.dat</code> и <code>.sub</code> как монотонный серый текст. Расширение выполняет полный контекстный парсинг синтаксиса KRL и подсвечивает ключевые слова, типы данных (<code>INT</code>, <code>REAL</code>, <code>BOOL</code>, <code>E6POS</code>), системные переменные (<code>$POS_ACT</code>, <code>$VEL.CP</code>), операторы и структурные FOLD-блоки KUKA WorkVisual.</li><li><strong>Практическая польза:</strong> Ошибки в опечатках и незакрытых кавычках видна мгновенно, снижая нагрузку на глаза инженера в условиях выездных пусконаладочных работ в цеху.</li><li><strong>До и После установки:</strong></li></ul><h4 id="до-установки-стандартныи-текст-без-подсветки" tabindex="-1">До установки (стандартный текст без подсветки): <a class="header-anchor" href="#до-установки-стандартныи-текст-без-подсветки" aria-label="Permalink to &quot;До установки (стандартный текст без подсветки):&quot;">​</a></h4><p><img src="'+e+'" alt="Syntax Highlighting До"></p><h4 id="после-установки-контрастная-подсветка-krl" tabindex="-1">После установки (Контрастная подсветка KRL): <a class="header-anchor" href="#после-установки-контрастная-подсветка-krl" aria-label="Permalink to &quot;После установки (Контрастная подсветка KRL):&quot;">​</a></h4><p><img src="'+l+'" alt="Syntax Highlighting После"></p><hr><h3 id="_2-набор-эксклюзивных-тем-kuka-6-kuka-themes" tabindex="-1">2. Набор эксклюзивных тем KUKA (6 KUKA Themes) <a class="header-anchor" href="#_2-набор-эксклюзивных-тем-kuka-6-kuka-themes" aria-label="Permalink to &quot;2. Набор эксклюзивных тем KUKA (6 KUKA Themes)&quot;">​</a></h3><ul><li><strong>Для чего нужна:</strong> Коллекция из 6 контрастных тем оформления, адаптированных для работы на промышленных ноутбуках при ярком цеховом освещении и на экранах SmartPAD: <ol><li><strong>Industrial Dark</strong> (фирменный стиль KUKA с промышленным оранжевым акцентом <code>#FF6600</code>)</li><li><strong>WorkVisual Dark</strong> (темная тема в стиле KUKA WorkVisual)</li><li><strong>WorkVisual Light</strong> (светлая тема для работы на улице и в светлых лабораториях)</li><li><strong>Midnight OLED</strong> (глубокий черный фон для экономии батареи ноутбука)</li><li><strong>Blueprint</strong> (инженерный чертежный стиль)</li><li><strong>Industrial Light</strong> (контрастная светлая тема)</li></ol></li><li><strong>Как вызывать:</strong> Нажмите <code>Ctrl + K</code>, затем <code>Ctrl + T</code> и выберите любую из тем KUKA.</li><li><strong>Скриншоты тем:</strong></li></ul><p><img src="'+i+'" alt="KUKA Industrial Theme 1"></p><p><img src="'+a+'" alt="KUKA Industrial Theme 2"></p><p><img src="'+r+'" alt="KUKA Industrial Theme 3"></p><p><img src="'+t+'" alt="KUKA Industrial Theme 4"></p><hr><h3 id="_3-умное-автодополнение-smart-autocomplete-kss-8-7" tabindex="-1">3. Умное автодополнение (Smart Autocomplete &amp; KSS 8.7) <a class="header-anchor" href="#_3-умное-автодополнение-smart-autocomplete-kss-8-7" aria-label="Permalink to &quot;3. Умное автодополнение (Smart Autocomplete &amp; KSS 8.7)&quot;">​</a></h3><ul><li><strong>Для чего нужна:</strong> При вводе символа <code>$</code> или букв переменных редактор открывает интерактивный список с подсказками по всем 350+ системным переменным KSS 8.7 (<code>$POS_ACT</code>, <code>$VEL_ACT</code>, <code>$BASE</code>, <code>$TOOL</code>, <code>$IN</code>, <code>$OUT</code>, <code>$MODE_OP</code>), а также пользовательским переменным из файлов <code>.dat</code> и подпрограммам.</li><li><strong>Практическая польза:</strong> Больше не нужно помнить наизусть точные имена системных структур KUKA или заглядывать в бумажные руководства.</li><li><strong>Демонстрация работы:</strong></li></ul><p><img src="'+n+'" alt="Smart Autocomplete Demo"></p><hr><h3 id="_4-мультиязычность-trilingual-nls-localization-—-en-ru-tr" tabindex="-1">4. Мультиязычность (Trilingual NLS Localization — EN / RU / TR) <a class="header-anchor" href="#_4-мультиязычность-trilingual-nls-localization-—-en-ru-tr" aria-label="Permalink to &quot;4. Мультиязычность (Trilingual NLS Localization — EN / RU / TR)&quot;">​</a></h3><ul><li><strong>Для чего нужна:</strong> Полная локализация интерфейса расширения, включая всплывающие подсказки (Hover), сообщений об ошибках, меню команд, боковые панели TreeView и дашборд Control Center на три языка: <strong>Русский</strong>, <strong>English</strong> и <strong>Турецкий (Türkçe)</strong>.</li><li><strong>Практическая польза:</strong> Инженерная команда на международных проектах (например, на автомобильных заводах в Турции, России или Европе) работает в привычной языковой среде. Язык подстраивается автоматически под локаль VS Code.</li></ul><hr><h3 id="_5-inlay-hints-для-сигналов-in-out-anin-anout" tabindex="-1">5. Inlay Hints для сигналов ($IN / $OUT / $ANIN / $ANOUT) <a class="header-anchor" href="#_5-inlay-hints-для-сигналов-in-out-anin-anout" aria-label="Permalink to &quot;5. Inlay Hints для сигналов ($IN / $OUT / $ANIN / $ANOUT)&quot;">​</a></h3><ul><li><strong>Для чего нужна:</strong> При работе с физическими входами и выходами робота в коде пишутся обезличенные индексы, например <code>$IN[1]</code> или <code>$OUT[4]</code>. Функция <strong>Inlay Hints</strong> вставляет виртуальный полупрозрачный текст прямо в редактор рядом с каналом (например, <code>$IN[1]</code> <code>: diPartReady</code>), извлекая имена сигналов из комментариев и <code>.dat</code> файлов.</li><li><strong>Практическая польза:</strong> Инженер видит назначение датчиков и клапанов прямо в коде, не открывая таблицу сигналов и не меняя исходный файл.</li><li><strong>Демонстрация работы:</strong></li></ul><p><img src="'+k+'" alt="Inlay Hints Demo"></p><hr><h3 id="_6-подсказки-при-наведении-hover-info-read-write-status" tabindex="-1">6. Подсказки при наведении (Hover Info &amp; Read/Write Status) <a class="header-anchor" href="#_6-подсказки-при-наведении-hover-info-read-write-status" aria-label="Permalink to &quot;6. Подсказки при наведении (Hover Info &amp; Read/Write Status)&quot;">​</a></h3><ul><li><strong>Для чего нужна:</strong> При наведении курсора мыши на любую переменную или системный параметр (например, <code>$VEL.CP</code>, <code>$POS_ACT</code>, <code>$AXIS_ACT</code>) появляется всплывающая карточка с официальным описанием KSS, типом данных, допустимым диапазоном значений и правами доступа (<strong>Read-Only / Read-Write</strong>).</li><li><strong>Практическая польза:</strong> Исключает попытки записи в переменные только для чтения (например, <code>$POS_ACT</code>) до загрузки на шкаф KRC.</li><li><strong>Демонстрация работы:</strong></li></ul><p><img src="'+s+'" alt="Hover Info Demo"></p><hr><h3 id="_7-кросс-фаиловая-навигация-src-↔-dat-go-to-definition" tabindex="-1">7. Кросс-файловая навигация (.src ↔ .dat Go-to-Definition) <a class="header-anchor" href="#_7-кросс-фаиловая-навигация-src-↔-dat-go-to-definition" aria-label="Permalink to &quot;7. Кросс-файловая навигация (.src ↔ .dat Go-to-Definition)&quot;">​</a></h3><ul><li><strong>For what it&#39;s needed / Для чего нужна:</strong> В структуре KRL логика движения находится в файле <code>.src</code>, а объявления координат точек <code>E6POS</code>, инструмента <code>$TOOL</code> и фреймов <code>$BASE</code> — в сопряжённом файле <code>.dat</code>. Функция навигации по нажатию <code>F12</code> или <code>Ctrl + Click</code> мгновенно переносит курсор от вызова точки в <code>.src</code> к её точному месту объявления в <code>.dat</code>.</li><li><strong>Демонстрация работы:</strong></li></ul><p><img src="'+d+'" alt="Go-to-Definition Demo"></p><hr><h3 id="_8-поиск-всех-ссылок-find-all-references-—-shift-alt-f12" tabindex="-1">8. Поиск всех ссылок (Find All References — <code>Shift+Alt+F12</code>) <a class="header-anchor" href="#_8-поиск-всех-ссылок-find-all-references-—-shift-alt-f12" aria-label="Permalink to &quot;8. Поиск всех ссылок (Find All References — `Shift+Alt+F12`)&quot;">​</a></h3><ul><li><strong>Для чего нужна:</strong> При нажатии <code>Shift + Alt + F12</code> на любой переменной, точке или названии подпрограммы открывается выплывающая панель VS Code, показывающая все места в проекте, где она используется.</li><li><strong>Практическая польза:</strong> Безопасное переименование и анализ влияния изменений перед удалением или модификацией точек.</li><li><strong>Демонстрация работы:</strong></li></ul><p><img src="'+c+'" alt="Find All References Demo"></p><hr><h3 id="_9-глобальныи-форматировщик-krl-code-formatter-indentation" tabindex="-1">9. Глобальный форматировщик KRL (Code Formatter &amp; Indentation) <a class="header-anchor" href="#_9-глобальныи-форматировщик-krl-code-formatter-indentation" aria-label="Permalink to &quot;9. Глобальный форматировщик KRL (Code Formatter &amp; Indentation)&quot;">​</a></h3><ul><li><strong>Для чего нужна:</strong> Вызов <code>Format Document</code> (<code>Shift + Alt + F</code>) автоматически форматирует неаккуратный код: выравнивает знаки равенства в блоках присвоений, выстраивает лесенку отступов для циклов <code>FOR</code>, <code>WHILE</code>, <code>LOOP</code> и условий <code>IF...THEN</code>, а также выравнивает структуру блоков <code>;FOLD / ;ENDFOLD</code>.</li><li><strong>Демонстрация работы:</strong></li></ul><p><img src="'+h+'" alt="Code Formatter Demo"></p><hr><h3 id="_10-быстрое-сворачивание-разворачивание-fold-quick-fold-toolbar" tabindex="-1">10. Быстрое сворачивание / разворачивание FOLD (Quick Fold Toolbar) <a class="header-anchor" href="#_10-быстрое-сворачивание-разворачивание-fold-quick-fold-toolbar" aria-label="Permalink to &quot;10. Быстрое сворачивание / разворачивание FOLD (Quick Fold Toolbar)&quot;">​</a></h3><ul><li><strong>Для чего нужна:</strong> В верхней правой панели редактора добавлены быстрые иконки 🙈 (<code>krl.foldAll</code>) и 📖 (<code>krl.unfoldAll</code>). Они позволяют в один клик свернуть все структуры FOLD Inline Forms KUKA или развернуть весь модуль для полного чтения.</li><li><strong>Демонстрация работы:</strong></li></ul><p><img src="'+u+'" alt="Quick Fold Toolbar Demo"></p><hr><h3 id="_11-полное-дерево-команд-kuka-commands" tabindex="-1">11. Полное дерево команд KUKA COMMANDS <a class="header-anchor" href="#_11-полное-дерево-команд-kuka-commands" aria-label="Permalink to &quot;11. Полное дерево команд KUKA COMMANDS&quot;">​</a></h3><ul><li><strong>Для чего нужна:</strong> Боковая панель <code>KUKA COMMANDS</code> в Activity Bar VS Code содержит структурированное дерево всех доступных инженерных команд расширения, распределенных по 4 категориям (Инструменты, Сеть, Очистка, Отчеты).</li><li><strong>Демонстрация работы:</strong></li></ul><p><img src="'+_+'" alt="KUKA COMMANDS Demo"></p><hr><h3 id="_12-панель-сигналов-krl-i-o-signals" tabindex="-1">12. Панель сигналов KRL I/O Signals <a class="header-anchor" href="#_12-панель-сигналов-krl-i-o-signals" aria-label="Permalink to &quot;12. Панель сигналов KRL I/O Signals&quot;">​</a></h3><ul><li><strong>Для чего нужна:</strong> Интерактивная боковая панель для обзора всех объявленных входов и выходов (<code>$IN</code>, <code>$OUT</code>, <code>SIGNAL</code>) робота в проекте с быстрой фильтрацией, поиском каналов и просмотром привязанных комментариев.</li><li><strong>Демонстрация работы:</strong></li></ul><p><img src="'+g+'" alt="KRL I/O Signals Demo"></p><hr><h3 id="_13-очистка-неиспользуемых-переменных-unused-variable-cleaner" tabindex="-1">13. Очистка неиспользуемых переменных (Unused Variable Cleaner) <a class="header-anchor" href="#_13-очистка-неиспользуемых-переменных-unused-variable-cleaner" aria-label="Permalink to &quot;13. Очистка неиспользуемых переменных (Unused Variable Cleaner)&quot;">​</a></h3><ul><li><strong>Для чего нужна:</strong> Команда <code>KRL: Clean Up Unused Variables</code> автоматически сканирует <code>.dat</code> файлы и находит объявленные переменные <code>DECL</code>, которые нигде не вызываются в алгоритме <code>.src</code>. Позволяет быстро очистить <code>.dat</code> файл без повреждения структуры FOLD метаданных.</li></ul><hr><h3 id="_14-очиститель-git-метаданных-workvisual-git-metadata-cleaner" tabindex="-1">14. Очиститель Git-метаданных WorkVisual (Git Metadata Cleaner) <a class="header-anchor" href="#_14-очиститель-git-метаданных-workvisual-git-metadata-cleaner" aria-label="Permalink to &quot;14. Очиститель Git-метаданных WorkVisual (Git Metadata Cleaner)&quot;">​</a></h3><ul><li><strong>Для чего нужна:</strong> KUKA WorkVisual при каждом сохранении замусоривает служебные заголовки <code>&amp;ACCESS RVP</code>, <code>&amp;REL 1</code>, <code>&amp;PARAM TEMPLATE</code>, что ломает диффы в системах контроля версий Git. Команда <code>KRL: Clean KUKA Git Metadata</code> аккуратно срезает переменный мусор, оставляя только чистую логику KRL.</li><li><strong>Демонстрация работы:</strong></li></ul><p><img src="'+m+'" alt="Git Metadata Cleaner Demo"></p><hr><h3 id="_15-сортировка-объявлении-sort-declarations" tabindex="-1">15. Сортировка объявлений (Sort Declarations) <a class="header-anchor" href="#_15-сортировка-объявлении-sort-declarations" aria-label="Permalink to &quot;15. Сортировка объявлений (Sort Declarations)&quot;">​</a></h3><ul><li><strong>Для чего нужна:</strong> Автоматически группирует и сортирует по алфавиту объявления типов данных (<code>BOOL</code>, <code>INT</code>, <code>REAL</code>, <code>FRAME</code>, <code>E6POS</code>, <code>E6AXIS</code>) в <code>.dat</code> файлах.</li><li><strong>Демонстрация работы:</strong></li></ul><p><img src="'+p+'" alt="Sort Declarations Demo"></p><hr><h2 id="👑-часть-2-pro-industrial-edition-features-премиум-функции" tabindex="-1">👑 Часть 2. Pro &amp; Industrial Edition Features (Премиум функции) <a class="header-anchor" href="#👑-часть-2-pro-industrial-edition-features-премиум-функции" aria-label="Permalink to &quot;👑 Часть 2. Pro &amp; Industrial Edition Features (Премиум функции)&quot;">​</a></h2><p>Профессиональные функции предназначены для системных интеграторов, инженеров промышленной безопасности и главных робототехников.</p><hr><h3 id="_16-панель-управления-kuka-control-center-v1-8-5-pro-hub" tabindex="-1">16. Панель управления KUKA Control Center (v1.8.5 Pro Hub) <a class="header-anchor" href="#_16-панель-управления-kuka-control-center-v1-8-5-pro-hub" aria-label="Permalink to &quot;16. Панель управления KUKA Control Center (v1.8.5 Pro Hub)&quot;">​</a></h3><ul><li><strong>Для чего нужна:</strong> Центральный нативный Fluent UI дашборд (<code>krl.openControlCenter</code>), предоставляющий доступ в 1 клик ко всем инженерным модулям Pro, статической аналитике проекта, счетчику Pro подписки, быстрой покупке лицензий через Lemon Squeezy и интеграции с технической поддержкой.</li><li><strong>Демонстрация работы:</strong></li></ul><p><img src="'+f+'" alt="KUKA Control Center Demo"></p><hr><h3 id="_17-интерактивная-обратная-связь-и-чат-в-vs-code-telegram-support-panel" tabindex="-1">17. Интерактивная обратная связь и чат в VS Code (Telegram Support Panel) <a class="header-anchor" href="#_17-интерактивная-обратная-связь-и-чат-в-vs-code-telegram-support-panel" aria-label="Permalink to &quot;17. Интерактивная обратная связь и чат в VS Code (Telegram Support Panel)&quot;">​</a></h3><ul><li><strong>Для чего нужна:</strong> Встроенная панель обратной связи в VS Code (<code>krl.openTelegramChat</code>) сопряжена с официальным Telegram-ботом поддержки <strong><code>@kukakrlbot</code></strong>. Позволяет инженеру из редактора отправить вопрос, скриншот или лог ошибки прямо разработчикам расширения.</li></ul><hr><h3 id="_18-автономная-консоль-администратора-поддержки-kukaadminhelpdesk-exe" tabindex="-1">18. Автономная Консоль Администратора Поддержки (<code>KukaAdminHelpdesk.exe</code>) <a class="header-anchor" href="#_18-автономная-консоль-администратора-поддержки-kukaadminhelpdesk-exe" aria-label="Permalink to &quot;18. Автономная Консоль Администратора Поддержки (`KukaAdminHelpdesk.exe`)&quot;">​</a></h3><ul><li><strong>Для чего нужна:</strong> Отдельное нативное Windows-приложение диспетчера для руководителей отделов автоматизации. Показывает онлайн-статус инженерных станций в цеху (🟢 ONLINE / 🟡 IDLE / 🔴 OFFLINE) и позволяет осуществлять централизованную поддержку пусконаладчиков.</li></ul><hr><h3 id="_19-krc-backup-diff-point-delta-inspector" tabindex="-1">19. KRC Backup Diff &amp; Point Delta Inspector <a class="header-anchor" href="#_19-krc-backup-diff-point-delta-inspector" aria-label="Permalink to &quot;19. KRC Backup Diff &amp; Point Delta Inspector&quot;">​</a></h3><ul><li><strong>Для чего нужна:</strong> Выбирает ZIP-архив бэкапа SmartPAD с робота (KRC4/KRC5) и сравнивает его с локальным проектом. Автоматически парсит координаты <code>E6POS</code>/<code>E6AXIS</code> и рассчитывает физическую дельту смещения точек по осям ($\\Delta X, \\Delta Y, \\Delta Z, \\Delta A, \\Delta B, \\Delta C$).</li><li><strong>Практическая польза:</strong> Предотвращает столкновения, если оператор в цеху подправил точку со SmartPAD вручную, а инженер на ноутбуке заливает старый проект.</li><li><strong>Демонстрация работы:</strong></li></ul><p><img src="'+K+'" alt="KRC Backup Diff Demo"></p><hr><h3 id="_20-интерактивныи-генератор-траектории-и-сниппетов-движения" tabindex="-1">20. Интерактивный генератор траекторий и сниппетов движения <a class="header-anchor" href="#_20-интерактивныи-генератор-траектории-и-сниппетов-движения" aria-label="Permalink to &quot;20. Интерактивный генератор траекторий и сниппетов движения&quot;">​</a></h3><ul><li><strong>Для чего нужна:</strong> Двухколоночный интерфейс для визульного конструирования движений KUKA: <code>PTP</code>, <code>LIN</code>, <code>CIRC</code>, <code>SPTP</code>, <code>SLIN</code>, <code>SCIRC</code> и блоков <code>SPLINE</code>. В режиме реального времени строит динамическую векторную SVG-схему траектории TCP с подсветкой векторов осей, промежуточных точек $P_0, XpAux, XpTarget$ и профиля рывка <code>$SGEAR_JERK</code>.</li></ul><hr><h3 id="_21-просмотрщик-блок-схем-control-flow-graph-flowchart" tabindex="-1">21. Просмотрщик блок-схем (Control Flow Graph / Flowchart) <a class="header-anchor" href="#_21-просмотрщик-блок-схем-control-flow-graph-flowchart" aria-label="Permalink to &quot;21. Просмотрщик блок-схем (Control Flow Graph / Flowchart)&quot;">​</a></h3><ul><li><strong>Для чего нужна:</strong> Превращает массивные файлы логики <code>.src</code> в интерактивную граф-диаграмму Mermaid SVG (<code>krl.showFlowchart</code>). Визуализирует условия <code>IF/THEN/ELSE</code>, циклы <code>LOOP</code>, ветвления <code>SWITCH/CASE</code>, таймеры и команды движения. Клик по подпрограмме мгновенно загружает её блок-схему (drill-down). Есть экспорт в SVG.</li><li><strong>Демонстрация работы:</strong></li></ul><p><img src="'+b+'" alt="Control Flow Graph Demo"></p><h4 id="примеры-векторных-блок-схем" tabindex="-1">Примеры векторных блок-схем: <a class="header-anchor" href="#примеры-векторных-блок-схем" aria-label="Permalink to &quot;Примеры векторных блок-схем:&quot;">​</a></h4><p><img src="'+S+'" alt="Cell Flowchart SVG"></p><hr><h3 id="_22-ethernetkrl-eki-suite-handler-generator" tabindex="-1">22. EthernetKRL (EKI) Suite &amp; Handler Generator <a class="header-anchor" href="#_22-ethernetkrl-eki-suite-handler-generator" aria-label="Permalink to &quot;22. EthernetKRL (EKI) Suite &amp; Handler Generator&quot;">​</a></h3><ul><li><strong>Для чего нужна:</strong> Модуль для работы с сетевым обменом KUKA EthernetKRL. Выполняет валидацию XML-схем взаимодействия с внешними PLC/Vision системами и автоматически генерирует полный KRL-модуль обработки сетевых сокетов (<code>EKI_Init</code>, <code>EKI_Open</code>, <code>EKI_Get*</code>, <code>EKI_Send*</code>).</li></ul><hr><h3 id="_23-диагностика-промышленнои-безопасности-safety-velocity-check" tabindex="-1">23. Диагностика промышленной безопасности (Safety &amp; Velocity Check) <a class="header-anchor" href="#_23-диагностика-промышленнои-безопасности-safety-velocity-check" aria-label="Permalink to &quot;23. Диагностика промышленной безопасности (Safety &amp; Velocity Check)&quot;">​</a></h3><ul><li><strong>Для чего нужна:</strong> Автоматический инспектор безопасности (<code>KRL: Run Safety Check</code>). Сканирует код на: <ol><li>Превышение безопасной скоростиCommissioning (<code>$VEL.CP &gt; 3.0 m/s</code>).</li><li>Запуск команд движения без предварительной инициализации активного инструмента <code>$TOOL</code> и базы <code>$BASE</code>.</li><li>Наличие невидимых символов кириллицы в исполняемых строках, выбывающих контроллер KRC в фатальную ошибку.</li></ol></li></ul><hr><h3 id="_24-ai-supportive-domain-context-tools-kuka-get-io-matrix-kuka-check-safety" tabindex="-1">24. AI-Supportive Domain Context Tools (<code>@kuka /get-io-matrix</code>, <code>@kuka /check-safety</code>) <a class="header-anchor" href="#_24-ai-supportive-domain-context-tools-kuka-get-io-matrix-kuka-check-safety" aria-label="Permalink to &quot;24. AI-Supportive Domain Context Tools (`@kuka /get-io-matrix`, `@kuka /check-safety`)&quot;">​</a></h3><ul><li><strong>Для чего нужна:</strong> Инструменты интеграции со встроенным ИИ (Google Antigravity IDE / GitHub Copilot). Передают точный контекст KSS 8.7, сигнальную матрицу I/O в JSON и результаты проверок безопасности в prompt ИИ, устраняя галлюцинации нейросетей при написании KRL кода.</li></ul><hr><h3 id="_25-3-point-frame-calculator-калькулятор-баз-и-инструментов" tabindex="-1">25. 3-Point Frame Calculator (Калькулятор баз и инструментов) <a class="header-anchor" href="#_25-3-point-frame-calculator-калькулятор-баз-и-инструментов" aria-label="Permalink to &quot;25. 3-Point Frame Calculator (Калькулятор баз и инструментов)&quot;">​</a></h3><ul><li><strong>Для чего нужна:</strong> Геометрический 3D-калькулятор системы координат (<code>krl.showCalculator</code>). Принимает координаты 3 опорных точек (Origin, X-Axis, XY-Plane) и мгновенно вычисляет матрицу трансформации и углы Эйлера (A, B, C) для настройки <code>BASE_DATA[x]</code>.</li></ul><hr><h3 id="_26-генератор-отчетов-приемки-quality-acceptance-report" tabindex="-1">26. Генератор отчётов приёмки (Quality Acceptance Report) <a class="header-anchor" href="#_26-генератор-отчетов-приемки-quality-acceptance-report" aria-label="Permalink to &quot;26. Генератор отчётов приёмки (Quality Acceptance Report)&quot;">​</a></h3><ul><li><strong>Для чего нужна:</strong> Выгружает структурированный HTML/JSON отчёт о качестве кода и соблюдении стандартов безопасности проекта. Идеально подходит для сдачи объекта техническому заказчику.</li></ul><hr><h2 id="🛠️-поддержка-и-покупка-pro-лицензии" tabindex="-1">🛠️ Поддержка и покупка Pro Лицензии <a class="header-anchor" href="#🛠️-поддержка-и-покупка-pro-лицензии" aria-label="Permalink to &quot;🛠️ Поддержка и покупка Pro Лицензии&quot;">​</a></h2><ul><li><strong>Приобрести Pro подписку:</strong> <a href="https://liskin.lemonsqueezy.com" target="_blank" rel="noreferrer">LiskinLabs Store (Lemon Squeezy)</a></li><li><strong>Инженерная поддержка в Telegram:</strong> <a href="https://t.me/kukakrlbot" target="_blank" rel="noreferrer">@kukakrlbot</a></li></ul>',115)])])}const w=A(L,[["render",I]]);export{G as __pageData,w as default};
